  public void reset(CharSequence buffer, int start, int end, int initialState) {
    int len = end - start;
    zzBuffer = new char[len];
    for (int i = 0; i < len; i++) {
      zzBuffer[i] = buffer.charAt(start + i);
    }
    zzCurrentPos = 0;
    zzMarkedPos = 0;
    zzStartRead = 0;
    zzEndRead = len;
    zzAtBOL = true;
    zzAtEOF = false;
    zzEOFDone = false;
    zzFinalHighSurrogate = 0;
    zzLexicalState = initialState;
    zzReader = java.io.Reader.nullReader();
    zzCharSequenceMode = true;
    percent_percent_count = 0;
    nesting = 0;
    tokenStart = -1;
  }


